import java.io.*;import java.util.*;public class Main {static class DSU {int[] parent;int[] size;public DSU(int n) {parent = new int[n + 1];size = new int[n + 1];for (int i = 1; i <= n; i++) {parent[i] = i;size[i] = 1;}}public int find(int i) {if (parent[i] == i) return i;return parent[i] = find(parent[i]);}public void union(int i, int j) {int rootI = find(i);int rootJ = find(j);if (rootI != rootJ) {if (size[rootI] < size[rootJ]) {int temp = rootI;rootI = rootJ;rootJ = temp;}parent[rootJ] = rootI;size[rootI] += size[rootJ];}}}public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));StringTokenizer st = new StringTokenizer(br.readLine());int n = Integer.parseInt(st.nextToken());int m = Integer.parseInt(st.nextToken());DSU dsu = new DSU(n);for (int i = 0; i < m; i++) {st = new StringTokenizer(br.readLine());int k = Integer.parseInt(st.nextToken());if (k > 1) {int first = Integer.parseInt(st.nextToken());for (int j = 1; j < k; j++) {dsu.union(first, Integer.parseInt(st.nextToken()));}} else if (k == 1) {st.nextToken();}}StringBuilder sb = new StringBuilder();for (int i = 1; i <= n; i++) {sb.append(dsu.size[dsu.find(i)]).append(" ");}System.out.println(sb.toString().trim());}}